const $=id=>document.getElementById(id);const content={
corexy:{title:'两路输入，控制一个平面',intro:'切换X、Y或斜向运动，比较两个电机的输入变化。',steps:['电机A、B保持在固定位置，通过两路输入协同驱动。','同向等量输入得到X方向运动；反向等量输入得到Y方向运动（按本图约定）。','导轨限定打印头的运动方向，横梁随Y位置一起移动。'],presets:[['x','沿X移动'],['y','沿Y移动'],['diagonal','斜向移动']],boundary:'输入关系采用 a=x+y、b=x−y 的归一化示意；正负号随电机与皮带方向约定变化。虚线表示输入关联，不是实机皮带绕线路径，未模拟张力。'},
guide:{title:'驱动负责移动，导轨负责约束',intro:'拖动进度，观察滑块沿直线运动；导轨和机架保持固定。',steps:['固定导轨形成运动参考。','滑块与导轨构成导向关系，限制横向偏移及部分转动。','滑块带动载荷直线移动；驱动力来自另设的电机与传动。'],boundary:'单轴移动副的功能示意，未绘出滚珠、预紧与摩擦，不是实际导轨受力仿真。'},
z:{title:'龙门升降，打印平台保持固定',intro:'四路Z驱动协同改变龙门高度，沿四角导轨上下移动。',steps:['打印平台固定在机架上，作为承托面。','四路Z驱动通过带传动改变龙门位置。','本演示只做同步升降；实际设备还可分别调整四角以校正龙门。'],boundary:'正视投影中错开显示四角支点。带传动、导轨位置与尺寸为功能示意，未模拟四角调平或电机控制。'},
feed:{title:'旋转输入，转成连续送料',intro:'齿轮夹持耗材，将它向热端推进；热端负责加热与出料。',steps:['电机带动减速及送料机构。','相向转动的送料齿轮夹持耗材，将耗材向下推进。','材料通过热端后从喷嘴出口挤出；热端不是送料驱动力。'],boundary:'将复杂的Clockwork2简化为一对送料齿轮与耗材路径。齿数、减速比、熔融与出料速度未按实机计算。'},
fan:{title:'叶轮旋转，空气沿风道流动',intro:'观察叶轮与气流的不同运动，理解旋转如何服务于冷却。',steps:['电机带动叶轮持续旋转。','叶轮对空气做功，形成流动。','风道引导气流；热端冷却与成形件冷却承担不同任务。'],boundary:'此图为叶轮和风道的通用功能示意，不代表实机叶片、风道几何、压力或流量。'}
};let type=new URLSearchParams(location.search).get('type')||'corexy',preset='x',phase=0,playing=true,last=0;
const line=(x1,y1,x2,y2,color='#697960',w=5,dash='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="${w}" ${dash?`stroke-dasharray="${dash}"`:''}/>`;
const rect=(x,y,w,h,fill='#36432e',r=5)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" fill="${fill}"/>`;
const text=(x,y,s,color='#c0d0b4',size=16)=>`<text x="${x}" y="${y}" fill="${color}" font-size="${size}" font-family="system-ui, sans-serif">${s}</text>`;
function wheel(x,y,r,angle,color='#c4d2bb'){let s=`<g transform="translate(${x} ${y}) rotate(${angle})"><circle r="${r}" fill="#182213" stroke="${color}" stroke-width="5"/>`;for(let i=0;i<12;i++){const a=i*Math.PI/6;s+=line(Math.cos(a)*(r-2),Math.sin(a)*(r-2),Math.cos(a)*(r+5),Math.sin(a)*(r+5),color,4)}s+=line(0,0,r-10,0,color,5)+`<circle r="7" fill="${color}"/></g>`;return s}
function render(){const t=phase/100*2*Math.PI,u=(1-Math.cos(t))/2;let s='',values=[];
if(type==='corexy'){const x=preset==='y'?0:(u-.5)*250,y=preset==='x'?0:(u-.5)*170,cx=380+x,cy=235-y,a=(x+y)/10,b=(x-y)/10;s=rect(174,70,412,320,'#222e1c')+rect(191,86,378,288,'#0f170c');s+=line(210,100,210,360,'#82917a',8)+line(550,100,550,360,'#82917a',8)+line(210,cy,550,cy,'#b7c3ac',12);s+=line(210,95,cx,cy,'#efa34b',2,'6 7')+line(550,95,cx,cy,'#96bdec',2,'6 7');s+=wheel(210,72,26,a*12,'#efa34b')+wheel(550,72,26,b*12,'#96bdec');s+=rect(cx-24,cy-24,48,48,'#c3ff3c',8)+text(cx-8,cy+6,'头','#18200e',18);s+=text(165,30,'电机 A','#efa34b')+text(512,30,'电机 B','#96bdec')+text(260,411,'X →    Y ↑  / 顶视功能示意','#8c9f7c',15);values=[['A输入',a.toFixed(1)],['B输入',b.toFixed(1)],['输出位置',`X ${(x/10).toFixed(1)} / Y ${(y/10).toFixed(1)}`]];
}else if(type==='guide'){const x=240+u*280;s=rect(140,320,480,32,'#26341e')+rect(160,220,440,18,'#a8b59c')+rect(160,244,440,15,'#4e5d44');s+=rect(x-45,195,90,82,'#b7c5ab',9)+rect(x-31,153,62,44,'#c3ff3c',6);s+=line(170,125,590,125,'#c3ff3c',2,'7 6')+text(270,106,'允许：沿导轨直线移动','#c3ff3c')+text(160,302,'固定导轨','#9faf91')+text(x-35,180,'载荷','#17200d',15);s+=text(185,390,'固定支承 + 导向约束 + 移动滑块','#9faf91');values=[['导轨','固定'],['滑块位置',(u*100).toFixed(0)+'%'],['运动形式','直线移动']];
}else if(type==='z'){const y=130+u*170;s=rect(165,65,430,325,'#23311d')+rect(185,85,390,280,'#0d150a');for(let i=0;i<4;i++){const x=205+i*115;s+=line(x,100,x,350,'#75846b',5)+line(x+9,100,x+9,350,'#936b38',2,'8 5')+wheel(x,360,16,-u*260,'#a8b89b')+rect(x-9,y-13,18,26,'#c3ff3c',4)}s+=rect(190,y,380,15,'#c3ff3c')+rect(355,y-29,50,28,'#aebfa0')+rect(200,330,360,12,'#c0c8b8')+text(245,320,'固定平台','#d3dfc9')+text(250,y+42,'升降龙门','#c3ff3c')+text(240,414,'四路Z驱动 / 同步升降示意','#90a67f',15);values=[['平台','固定'],['龙门高度',Math.round((1-u)*100)+'%'],['驱动形式','四路带传动']];
}else if(type==='feed'){s=rect(230,80,300,190,'#23311d')+rect(250,100,260,150,'#10190b');s+=rect(375,40,10,282,'#e7c994',2);s+=wheel(325,172,45,phase*3.6,'#b6c4aa')+wheel(435,172,45,-phase*3.6,'#b6c4aa');for(let i=0;i<7;i++){const y=40+((i*40+phase*2.8)%280);s+=line(375,y,385,y,'#b17b38',3)}s+=rect(351,284,58,40,'#bbbdaf',3)+rect(357,326,46,25,'#dc8344',3)+`<path d="M361 351h38l-15 22h-8Z" fill="#d9ac6d"/>`+line(380,373,380,395,'#e9af68',5);s+=text(255,33,'耗材向下推进','#e7c994')+text(465,309,'热端','#d8a276')+text(465,354,'喷嘴出口','#d8a276')+line(410,307,452,307,'#d8a276',1);values=[['电机输入','旋转'],['耗材输出','向下送料'],['热端作用','加热 / 成形']];
}else {s=rect(175,90,240,260,'#26331f',18)+`<circle cx="295" cy="220" r="99" fill="#0b1208" stroke="#718566" stroke-width="6"/>`;s+=`<g transform="translate(295 220) rotate(${phase*7.2})">`;for(let i=0;i<7;i++)s+=`<path d="M0 0Q-5-65 40-83Q85-60 19-9Z" transform="rotate(${i*360/7})" fill="#a7b89b"/>`;s+=`<circle r="24" fill="#c3ff3c"/></g>`+rect(415,135,190,170,'#1b2914',10);for(let i=0;i<8;i++){const x=425+(i*25+phase*2)%170;s+=line(x,170,x+15,170,'#9dc9dc',2)+line(x,220,x+15,220,'#9dc9dc',2)+line(x,270,x+15,270,'#9dc9dc',2)}s+=text(230,390,'叶轮旋转','#bfd0b0')+text(450,390,'空气沿风道流动','#9dc9dc');values=[['输入','电机旋转'],['传递','叶轮带动空气'],['输出','定向气流']];}
$('scene').innerHTML=s;$('readouts').innerHTML=values.map(([k,v])=>`<div><span>${k}</span><b>${v}</b></div>`).join('');$('phase').value=phase;$('phaseValue').textContent=Math.round(phase)+'%';}
function setType(value){type=content[value]?value:'corexy';phase=0;const c=content[type];$('title').textContent=c.title;$('intro').textContent=c.intro;$('steps').innerHTML=c.steps.map(x=>'<li>'+x+'</li>').join('');$('boundary').innerHTML=c.boundary+' <a href="https://docs.vorondesign.com/hardware.html" target="_blank" rel="noopener">官方结构资料 ↗</a>';document.querySelectorAll('[data-type]').forEach(b=>b.classList.toggle('active',b.dataset.type===type));$('presets').innerHTML='';for(const [id,label]of c.presets||[]){const b=document.createElement('button');b.textContent=label;b.classList.toggle('active',preset===id);b.onclick=()=>{preset=id;document.querySelectorAll('#presets button').forEach(x=>x.classList.toggle('active',x===b));render()};$('presets').appendChild(b)}render()}
document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>setType(b.dataset.type));$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'Ⅱ 暂停':'▶ 播放'};$('phase').oninput=e=>{playing=false;$('play').textContent='▶ 播放';phase=+e.target.value;render()};function tick(t){const dt=Math.min(100,t-last);last=t;if(playing){phase=(phase+dt*.009)%100;render()}requestAnimationFrame(tick)}setType(type);requestAnimationFrame(tick);
